import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/00-Recommended_Framework.html","title":"Apollo MMORPG 自研框架（建议版）","lang":"en-US","frontmatter":{},"filePathRelative":"00-Recommended_Framework.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`00-Recommended_Framework.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="apollo-mmorpg-自研框架-建议版" tabindex="-1"><a class="header-anchor" href="#apollo-mmorpg-自研框架-建议版"><span>Apollo MMORPG 自研框架（建议版）</span></a></h1><h2 id="_1-目标与原则" tabindex="-1"><a class="header-anchor" href="#_1-目标与原则"><span>1. 目标与原则</span></a></h2><ul><li><strong>统一口径</strong>：文档、指标、实施计划围绕同一套技术栈与服务拆分，避免再出现 SDNet 等历史遗留描述。</li><li><strong>跨平台网络内核</strong>：Linux 采用 <code>io_uring</code> (fallback <code>epoll</code>)，Windows 采用 IOCP；对上提供统一的 NetCore。</li><li><strong>性能目标</strong>：单服 5000+ CCU，核心操作 P99 &lt; 60 ms，99.95% 可用；每份文档均以此为 SLO。</li><li><strong>关注点分离</strong>：AOI、Battle、Social、DataProxy 等服务各司其职；存储/计算/日志链路互不阻塞。</li><li><strong>工程化</strong>：C++20 + CMake Presets + vcpkg；CI 覆盖构建、单元/压力测试；Prometheus/Grafana 观测；Kafka→ClickHouse TLog。</li></ul><h2 id="_2-技术栈" tabindex="-1"><a class="header-anchor" href="#_2-技术栈"><span>2. 技术栈</span></a></h2><table><thead><tr><th>层级</th><th>技术</th></tr></thead><tbody><tr><td>语言 &amp; 标准</td><td>C++20，MSVC 2022 / GCC 11+，<code>std::pmr</code> + RAII</td></tr><tr><td>构建</td><td>CMake Presets，vcpkg manifest，clang-format/tidy</td></tr><tr><td>网络</td><td>自研 NetCore：Linux <code>io_uring</code> + fallback <code>epoll</code>，Windows IOCP；支持 TCP/KCP/WebSocket</td></tr><tr><td>序列化</td><td>Protobuf/gRPC（内部），REST/JSON（对外运营/GM）</td></tr><tr><td>配置</td><td>Excel→Lua/JSON pipeline，配置中心 + FileWatcher + 版本治理</td></tr><tr><td>数据</td><td>MySQL 8.0 主从 + 分库分表；Redis Cluster；Kafka + ClickHouse（BI/TLog）</td></tr><tr><td>逻辑</td><td>Lua 5.4 + sol2，热更沙箱；ECS 架构 + 属性容器</td></tr><tr><td>运维</td><td>Consul/Etcd 服务发现，Prometheus + Grafana，Jaeger Trace，ELK 日志</td></tr></tbody></table><h2 id="_3-推荐架构" tabindex="-1"><a class="header-anchor" href="#_3-推荐架构"><span>3. 推荐架构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌───────────────────────── 玩家客户端 ─────────────────────────┐</span>
<span class="line">│ Unity / UE / Mobile                                         │</span>
<span class="line">└───────────────┬─────────────────────────────────────────────┘</span>
<span class="line">                │TCP/KCP + Protobuf</span>
<span class="line">        ┌───────▼───────┐</span>
<span class="line">        │ CDN / WAF     │</span>
<span class="line">        └───────┬───────┘</span>
<span class="line">                │L4 LB</span>
<span class="line">┌───────────────▼──────────────── 接入层 ─────────────────────┐</span>
<span class="line">│ GateServer Cluster                                           │</span>
<span class="line">│ • 连接/心跳 • 加密/防刷 • 消息路由 • 限流/灰度 • Session     │</span>
<span class="line">└───────┬────────────────────────────────────────────────────┘</span>
<span class="line">        │NetCore (TCP/KCP + Proto)</span>
<span class="line">┌───────▼────────┐</span>
<span class="line">│ WorldServer     │  玩家流量主干</span>
<span class="line">└─┬───────────────┘</span>
<span class="line">  │玩家生命周期 / 场景调度 / Consul</span>
<span class="line">  ▼</span>
<span class="line">┌───────────────┐          ┌───────────────────┐</span>
<span class="line">│ Scene Orchestr.│─spawn→  │ ZoneServer xN      │ (ECS/战斗/任务)</span>
<span class="line">└────┬──────────┘          └────┬──────────────┘</span>
<span class="line">     │实例生命周期                  │调用</span>
<span class="line">     │                             ▼</span>
<span class="line">     │                     ┌──────────────┐</span>
<span class="line">     │                     │ AOI Service  │ (独立位置/广播)</span>
<span class="line">     │                     └────┬─────────┘</span>
<span class="line">     │                           │Enter/Leave</span>
<span class="line">     │                           ▼</span>
<span class="line">     │                     ┌──────────────┐</span>
<span class="line">     │                     │ Battle Service│ (可选大型战斗)</span>
<span class="line">     │                     └────┬─────────┘</span>
<span class="line">     │                           │技能结算</span>
<span class="line">     ▼                           ▼</span>
<span class="line">┌──────────────┐        ┌─────────────────────┐</span>
<span class="line">│ Social Svc   │        │ DataProxy            │</span>
<span class="line">│ (Chat/Guild/ │&lt;------&gt;│ (Redis/MySQL 封装)   │</span>
<span class="line">│ Match/Rank…) │        └────┬────────────────┘</span>
<span class="line">└────┬─────────┘             │SQL/Cache</span>
<span class="line">     │                        ▼</span>
<span class="line">     │                ┌────────────────────────┐</span>
<span class="line">     │                │ MySQL Cluster / Redis  │</span>
<span class="line">     │                └────────────────────────┘</span>
<span class="line">     │日志</span>
<span class="line">     ▼</span>
<span class="line">┌──────────────────────────────┐</span>
<span class="line">│ LogAgent → Kafka → ClickHouse│</span>
<span class="line">└──────────────────────────────┘</span>
<span class="line"></span>
<span class="line">┌───────────────────────── 运维/运营 ─────────────────────────┐</span>
<span class="line">│ GM / BI / 数据服务 / SDK                                   │</span>
<span class="line">└────┬───────────────────────────────────────────────────────┘</span>
<span class="line">     │HTTP/gRPC</span>
<span class="line">┌────▼──────────┐</span>
<span class="line">│ Ops API Svc   │ (可选，负责 GM、BI、工具接入)</span>
<span class="line">└────┬──────────┘</span>
<span class="line">     │内部 gRPC</span>
<span class="line">     ▼</span>
<span class="line">┌──────────────┐</span>
<span class="line">│ Social / Data │ (复用 DataProxy / Social 模块能力)</span>
<span class="line">└──────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-核心模块职责" tabindex="-1"><a class="header-anchor" href="#_4-核心模块职责"><span>4. 核心模块职责</span></a></h2><ul><li><strong>GateServer</strong>：基于 NetCore 的连接管理、限流、加密、消息去重、路由；支持灰度和流量复制。与 WorldServer 直接协作，其他后台接口不经过 Gate。</li><li><strong>WorldServer</strong>：全局场景索引、跨服活动、账号登录态、玩家迁移 FSM；与 Consul/Etcd 交互控制调度。</li><li><strong>Scene Orchestrator + ZoneServer</strong>：ZoneServer 负责具体场景逻辑与 ECS/战斗；Orchestrator 负责实例生命周期管理、资源池、平滑扩容。对于固定地图或塔防类玩法，可提供 “Compact GameServer” 形态，将 Scene/AOI/Battle 合并在单进程运行，仍复用 NetCore、DataProxy、Transport 等基础设施，后续需要扩展时可平滑切换回分层架构。</li><li><strong>AOI Service</strong>：持有实体位置和 AOI 半径，输出 Enter/Leave/Sync 事件，支持 AOI 分片和跨区广播；在 Compact 模式下可内嵌于单进程逻辑层。</li><li><strong>Battle Service（可选）</strong>：为大型团战/副本提供独立结算流水线，减轻 ZoneServer；塔防或轻量战斗可直接使用 Compact GameServer 内置战斗模块。</li><li><strong>DataProxy</strong>：封装 Redis/MySQL，提供缓存一致性框架、写回策略、TLog 触发；供 Zone/AOI/Social 使用。</li><li><strong>Social Services</strong>：Chat/Guild/Match/Rank/Mail/Trade 等按业务拆分，统一通过 DataProxy 访问数据，可同时为玩家实时链路与运维/GM API 提供能力。</li><li><strong>LogAgent/TLog</strong>：从各模块收集行为日志→Kafka→实时监控(Flink)/离线分析(ClickHouse)。</li></ul><h2 id="_5-缺失文档-下一步" tabindex="-1"><a class="header-anchor" href="#_5-缺失文档-下一步"><span>5. 缺失文档 &amp; 下一步</span></a></h2><p>（已在当前仓库中逐步补齐：NetCore、Transport、AOI、DataProxy、API、实施计划等文档。后续若引入新模块，再按需更新此列表。）</p><p>确认此框架后，可逐章替换现有 docs，并把实施计划/需求池同步更新，再展开具体模块的技术细节讨论。</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};